const config = $input.first().json;

const digiformaApiUrl = config.digiformaApiUrl;
const digiformaApiToken = config.digiformaApiToken;
const appCacheUrl = config.appCacheUrl;
const cacheSecret = config.cacheSecret;

const targetYear = Number(config.targetYear || 2026);
const pipelineState = String(config.pipelineState || 'ongoing');
const onlyActive = Boolean(config.onlyActive);
const pageSize = Number(config.pageSize || 10);
const maxPages = Number(config.maxPages || 20);
const maxSessionsDetails = Number(config.maxSessionsDetails || 30);
const includeTodaySlots = Boolean(config.includeTodaySlots);
const postToApp = Boolean(config.postToApp);

if (!digiformaApiUrl) {
  throw new Error('digiformaApiUrl manquant dans le node Config.');
}

if (!digiformaApiToken || digiformaApiToken === 'COLLE_TON_TOKEN_DIGIFORMA_ICI') {
  throw new Error('digiformaApiToken manquant dans le node Config.');
}

async function digiformaGraphQLRequest(query, variables = {}) {
  const response = await fetch(digiformaApiUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${digiformaApiToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      query,
      variables
    })
  });

  const payload = await response.json();

  if (!response.ok) {
    const message = Array.isArray(payload.errors)
      ? payload.errors.map((error) => error.message).join(' | ')
      : `HTTP ${response.status}`;

    throw new Error(`Erreur Digiforma : ${message}`);
  }

  if (payload.errors && payload.errors.length > 0) {
    throw new Error(payload.errors.map((error) => error.message).join(' | '));
  }

  return payload.data;
}

async function fetchTrainingSessionsLight() {
  const query = `
    query GetTrainingSessionsLight(
      $pagination: Pagination,
      $filters: TrainingSessionFilters
    ) {
      trainingSessions(
        pagination: $pagination,
        filters: $filters
      ) {
        id
        name
        code
        startDate
        endDate
        pipelineState
      }
    }
  `;

  const filters = buildTrainingSessionFilters();
  const allSessions = [];

  for (let page = 1; page <= maxPages; page++) {
    const data = await digiformaGraphQLRequest(query, {
      pagination: {
        page,
        size: pageSize
      },
      filters
    });

    const sessions = Array.isArray(data.trainingSessions)
      ? data.trainingSessions
      : [];

    allSessions.push(...sessions);

    if (sessions.length < pageSize) {
      break;
    }
  }

  return allSessions;
}

function buildTrainingSessionFilters() {
  return {
    startedBefore: `${targetYear}-12-31`,
    endedAfter: `${targetYear}-01-01`
  };
}

async function fetchTrainingSessionDetails(sessionId) {
  const query = `
    query GetTrainingSessionDetails($id: ID!) {
      trainingSession(id: $id) {
        id
        name
        code
        startDate
        endDate
        pipelineState
        trainingType
        type
        timezone

        trainees {
          id
          firstname
          lastname
          email
          phone
          phoneSecondary
          status
        }

        trainingSessionSlots {
          id
          date
          startTime
          endTime
          slot

          signatures {
            signature
            type
            customerTrainee {
              id
              trainee {
                id
                firstname
                lastname
                email
                phone
                phoneSecondary
              }
            }
          }

          customerTrainees {
            id
            attendanceProofUrl
            extranetUrl
            trainee {
              id
              firstname
              lastname
              email
              phone
              phoneSecondary
            }
            signatures {
              signature
              type
              dates {
                id
                date
                startTime
                endTime
              }
            }
          }

          subsession {
            id
            name
          }
        }
      }
    }
  `;

  const data = await digiformaGraphQLRequest(query, {
    id: sessionId
  });

  return data.trainingSession || null;
}

function isAllowedPipelineState(session) {
  if (!onlyActive) {
    return true;
  }

  if (!pipelineState || pipelineState === 'all') {
    return true;
  }

  return String(session.pipelineState || '').toLowerCase() === pipelineState.toLowerCase();
}

function isTargetYearSession(session) {
  const yearStart = new Date(`${targetYear}-01-01T00:00:00`);
  const yearEnd = new Date(`${targetYear}-12-31T23:59:59`);

  const startDate = parseDate(session.startDate);
  const endDate = parseDate(session.endDate);

  if (!startDate && !endDate) {
    return false;
  }

  if (startDate && endDate) {
    return startDate <= yearEnd && endDate >= yearStart;
  }

  if (startDate && !endDate) {
    return startDate >= yearStart && startDate <= yearEnd;
  }

  if (!startDate && endDate) {
    return endDate >= yearStart && endDate <= yearEnd;
  }

  return false;
}

function parseDate(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
}

function buildPlanningResults(sessions) {
  const results = [];

  sessions.forEach((session) => {
    const trainees = Array.isArray(session.trainees) ? session.trainees : [];
    const slots = Array.isArray(session.trainingSessionSlots) ? session.trainingSessionSlots : [];

    trainees.forEach((trainee) => {
      const traineeSlots = findSlotsForTrainee(trainee, slots);
      const status = getPlanningStatus({ session, trainee, traineeSlots, sessionSlots: slots });

      results.push({
        learnerId: trainee.id || '',
        fullName: buildFullName(trainee.firstname, trainee.lastname),
        email: trainee.email || '',
        learnerStatus: trainee.status || '',
        sessionId: session.id || '',
        sessionName: session.name || '',
        sessionCode: session.code || '',
        sessionStatus: session.pipelineState || '',
        sessionStartDate: session.startDate || '',
        sessionEndDate: session.endDate || '',
        slotsCount: traineeSlots.length,
        totalSessionSlots: slots.length,
        status
      });
    });
  });

  return results;
}

function findSlotsForTrainee(trainee, slots) {
  const traineeId = String(trainee.id || '');
  const traineeEmail = cleanEmail(trainee.email);

  return slots.filter((slot) => {
    const customerTrainees = Array.isArray(slot.customerTrainees) ? slot.customerTrainees : [];

    const hasDirectTraineeMatch = customerTrainees.some((customerTrainee) => {
      const linkedTrainee = customerTrainee.trainee;

      if (!linkedTrainee) {
        return false;
      }

      return isSameTrainee(linkedTrainee, traineeId, traineeEmail);
    });

    if (hasDirectTraineeMatch) {
      return true;
    }

    return customerTrainees.length === 0;
  });
}

function getPlanningStatus({ session, trainee, traineeSlots, sessionSlots }) {
  if (!session.startDate || !session.endDate) {
    return {
      code: 'warning',
      label: 'Session sans dates complètes',
      action: 'Vérifier les dates de début et de fin de session dans Digiforma.'
    };
  }

  if (!Array.isArray(sessionSlots) || sessionSlots.length === 0) {
    return {
      code: 'missing',
      label: 'Aucun créneau session',
      action: 'Ajouter des créneaux de formation dans la session Digiforma.'
    };
  }

  if (!trainee.email) {
    return {
      code: 'warning',
      label: 'Email apprenant manquant',
      action: 'Compléter la fiche apprenant dans Digiforma.'
    };
  }

  if (traineeSlots.length === 0) {
    return {
      code: 'missing',
      label: 'Planning manquant',
      action: 'Vérifier l’affectation de l’apprenant aux créneaux, modules ou sous-sessions.'
    };
  }

  if (traineeSlots.length < 3) {
    return {
      code: 'warning',
      label: 'Planning possiblement incomplet',
      action: 'Contrôler que l’apprenant possède bien tous ses créneaux de formation.'
    };
  }

  return {
    code: 'ok',
    label: 'Planning OK',
    action: 'Aucune action nécessaire.'
  };
}

function buildSignatureReminders(sessions) {
  const reminders = [];

  sessions.forEach((session) => {
    const sessionTrainees = Array.isArray(session.trainees) ? session.trainees : [];
    const slots = Array.isArray(session.trainingSessionSlots) ? session.trainingSessionSlots : [];

    slots.forEach((slot) => {
      if (!isPastSlot(slot)) {
        return;
      }

      const concernedTrainees = getConcernedTraineesForSlot(slot, sessionTrainees);

      concernedTrainees.forEach((traineeContext) => {
        const trainee = traineeContext.trainee;
        const customerTrainee = traineeContext.customerTrainee;

        if (!trainee) {
          return;
        }

        const hasSignature = hasValidSignatureForSlot({ slot, trainee, customerTrainee });

        if (hasSignature) {
          return;
        }

        reminders.push(buildReminderItem({ session, slot, trainee, customerTrainee }));
      });
    });
  });

  return sortReminders(removeDuplicateReminders(reminders));
}

function getConcernedTraineesForSlot(slot, sessionTrainees) {
  const customerTrainees = Array.isArray(slot.customerTrainees) ? slot.customerTrainees : [];

  if (customerTrainees.length > 0) {
    return customerTrainees
      .filter((customerTrainee) => customerTrainee && customerTrainee.trainee)
      .map((customerTrainee) => ({ trainee: customerTrainee.trainee, customerTrainee }));
  }

  return sessionTrainees.map((trainee) => ({ trainee, customerTrainee: null }));
}

function hasValidSignatureForSlot({ slot, trainee, customerTrainee }) {
  const slotSignatures = Array.isArray(slot.signatures) ? slot.signatures : [];
  const customerTraineeSignatures = Array.isArray(customerTrainee?.signatures) ? customerTrainee.signatures : [];

  const traineeId = String(trainee.id || '');
  const traineeEmail = cleanEmail(trainee.email);

  const hasSlotSignature = slotSignatures.some((signature) => {
    if (!isSignatureFilled(signature)) {
      return false;
    }

    const signatureTrainee = signature.customerTrainee?.trainee;

    if (!signatureTrainee) {
      return false;
    }

    return isSameTrainee(signatureTrainee, traineeId, traineeEmail);
  });

  if (hasSlotSignature) {
    return true;
  }

  return customerTraineeSignatures.some((signature) => {
    if (!isSignatureFilled(signature)) {
      return false;
    }

    const dates = Array.isArray(signature.dates) ? signature.dates : [];

    if (dates.length === 0) {
      return true;
    }

    return dates.some((dateSlot) => String(dateSlot.id || '') === String(slot.id || ''));
  });
}

function buildReminderItem({ session, slot, trainee, customerTrainee }) {
  const slotDate = slot.date || '';
  const startTime = normalizeTime(slot.startTime);
  const endTime = normalizeTime(slot.endTime);
  const daysLate = computeDaysLate(slotDate);
  const priority = computePriority(daysLate);
  const fullName = buildFullName(trainee.firstname, trainee.lastname);
  const firstName = trainee.firstname || '';
  const sessionName = session.name || 'votre formation';
  const extranetUrl = customerTrainee?.extranetUrl || '';

  return {
    id: buildReminderId(session, slot, trainee),
    priority,
    daysLate,
    learnerId: trainee.id || '',
    fullName,
    firstName,
    lastName: trainee.lastname || '',
    email: trainee.email || '',
    phone: trainee.phone || trainee.phoneSecondary || '',
    customerTraineeId: customerTrainee?.id || '',
    extranetUrl,
    attendanceProofUrl: customerTrainee?.attendanceProofUrl || '',
    sessionId: session.id || '',
    sessionName,
    sessionCode: session.code || '',
    sessionStatus: session.pipelineState || '',
    sessionStartDate: session.startDate || '',
    sessionEndDate: session.endDate || '',
    slotId: slot.id || '',
    slotDate,
    startTime,
    endTime,
    slotLabel: slot.slot || '',
    subsessionName: slot.subsession?.name || '',
    status: {
      code: 'missing_signature',
      label: 'Émargement non signé',
      action: 'Relancer l’apprenant pour signature de son émargement Digiforma.'
    },
    messages: {
      email: buildEmailReminderMessage({ firstName, sessionName, slotDate, startTime, endTime, extranetUrl }),
      whatsapp: buildWhatsappReminderMessage({ firstName, sessionName, slotDate, startTime, endTime, extranetUrl })
    }
  };
}

function buildEmailReminderMessage({ firstName, sessionName, slotDate, startTime, endTime, extranetUrl }) {
  const formattedDate = formatDateFR(slotDate);
  const linkSentence = extranetUrl ? `\n\nLien utile : ${extranetUrl}` : '';

  return [
    `Bonjour ${firstName || ''},`.trim(),
    '',
    `Sauf erreur de notre part, votre émargement du ${formattedDate} de ${startTime} à ${endTime} pour la formation "${sessionName}" n’a pas encore été signé.`,
    '',
    'Pouvez-vous vous connecter à votre espace apprenant Digiforma afin de régulariser votre signature, s’il vous plaît ?',
    '',
    'Cette signature est importante, car elle permet de justifier officiellement votre présence en formation.',
    linkSentence,
    '',
    'Merci d’avance pour votre retour.',
    '',
    'Cordialement,',
    'Australe Formation'
  ].join('\n');
}

function buildWhatsappReminderMessage({ firstName, sessionName, slotDate, startTime, endTime, extranetUrl }) {
  const formattedDate = formatDateFR(slotDate);
  const linkPart = extranetUrl ? ` Lien : ${extranetUrl}` : '';

  return `Bonjour ${firstName || ''}, sauf erreur de notre part, votre émargement du ${formattedDate} de ${startTime} à ${endTime} pour la formation "${sessionName}" n’a pas encore été signé. Pouvez-vous vous connecter à votre espace Digiforma pour le régulariser, s’il vous plaît ? Merci, Australe Formation.${linkPart}`.trim();
}

function isPastSlot(slot) {
  if (!slot.date) {
    return false;
  }

  const now = new Date();
  const endTime = normalizeTime(slot.endTime || '23:59');
  const slotEndDate = new Date(`${slot.date}T${endTime}`);

  if (Number.isNaN(slotEndDate.getTime())) {
    return false;
  }

  if (includeTodaySlots) {
    return slotEndDate < now;
  }

  return toDateKey(slotEndDate) < toDateKey(now);
}

function isSignatureFilled(signature) {
  return Boolean(String(signature?.signature || '').trim());
}

function isSameTrainee(signatureTrainee, traineeId, traineeEmail) {
  const signatureTraineeId = String(signatureTrainee.id || '');
  const signatureTraineeEmail = cleanEmail(signatureTrainee.email);

  if (traineeId && signatureTraineeId && signatureTraineeId === traineeId) {
    return true;
  }

  return Boolean(traineeEmail && signatureTraineeEmail && signatureTraineeEmail === traineeEmail);
}

function computeDaysLate(slotDate) {
  const date = new Date(`${slotDate}T00:00:00`);

  if (Number.isNaN(date.getTime())) {
    return 0;
  }

  const today = new Date();
  const todayMidnight = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const slotMidnight = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const diffMs = todayMidnight.getTime() - slotMidnight.getTime();

  return Math.max(0, Math.floor(diffMs / 86400000));
}

function computePriority(daysLate) {
  if (daysLate >= 7) return 'critical';
  if (daysLate >= 3) return 'high';
  return 'normal';
}

function sortReminders(reminders) {
  const priorityWeight = { critical: 1, high: 2, normal: 3 };

  return reminders.sort((a, b) => {
    const priorityDiff = (priorityWeight[a.priority] || 99) - (priorityWeight[b.priority] || 99);

    if (priorityDiff !== 0) {
      return priorityDiff;
    }

    return b.daysLate - a.daysLate;
  });
}

function removeDuplicateReminders(reminders) {
  const map = new Map();

  reminders.forEach((reminder) => {
    if (!map.has(reminder.id)) {
      map.set(reminder.id, reminder);
    }
  });

  return Array.from(map.values());
}

function normalizeTime(value) {
  const stringValue = String(value || '').trim();

  if (!stringValue) return '00:00';
  if (/^\d{2}:\d{2}$/.test(stringValue)) return stringValue;
  if (/^\d{2}:\d{2}:\d{2}$/.test(stringValue)) return stringValue.slice(0, 5);

  return stringValue;
}

function formatDateFR(value) {
  if (!value) return 'date non renseignée';

  const date = new Date(`${value}T00:00:00`);

  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat('fr-FR').format(date);
}

function toDateKey(date) {
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, '0'),
    String(date.getDate()).padStart(2, '0')
  ].join('-');
}

function buildFullName(firstname, lastname) {
  return [firstname, lastname].filter(Boolean).join(' ').trim();
}

function cleanEmail(value) {
  return String(value || '').trim().toLowerCase();
}

function buildReminderId(session, slot, trainee) {
  return ['reminder', session.id || 'session', slot.id || 'slot', trainee.id || cleanEmail(trainee.email) || 'trainee'].join('_');
}

function buildSummary({ lightSessions, filteredSessions, detailedSessions, failedSessions, planningResults, reminders }) {
  return {
    generatedAt: new Date().toISOString(),
    source: 'n8n',
    filters: {
      targetYear,
      pipelineState,
      onlyActive,
      maxSessionsDetails,
      includeTodaySlots
    },
    planning: {
      totalSessionsFetched: lightSessions.length,
      totalSessionsAfterFilter: filteredSessions.length,
      totalSessions: detailedSessions.length,
      totalSessionsFailed: failedSessions.length,
      failedSessions,
      totalLearners: planningResults.length,
      totalOk: planningResults.filter((item) => item.status.code === 'ok').length,
      totalMissing: planningResults.filter((item) => item.status.code === 'missing').length,
      totalWarning: planningResults.filter((item) => item.status.code === 'warning').length,
      results: planningResults
    },
    reminders: {
      totalReminders: reminders.length,
      totalCritical: reminders.filter((item) => item.priority === 'critical').length,
      totalHigh: reminders.filter((item) => item.priority === 'high').length,
      totalNormal: reminders.filter((item) => item.priority === 'normal').length,
      results: reminders
    }
  };
}

async function postCacheToApp(cachePayload) {
  if (!postToApp) {
    return {
      posted: false,
      reason: 'postToApp désactivé'
    };
  }

  if (!appCacheUrl) {
    return {
      posted: false,
      reason: 'appCacheUrl manquant'
    };
  }

  const response = await fetch(appCacheUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Australe-Cache-Secret': cacheSecret || ''
    },
    body: JSON.stringify(cachePayload)
  });

  const text = await response.text();

  if (!response.ok) {
    throw new Error(`Erreur POST app cache ${response.status} : ${text}`);
  }

  return {
    posted: true,
    status: response.status,
    response: text
  };
}

const lightSessions = await fetchTrainingSessionsLight();

const filteredSessions = lightSessions
  .filter(isTargetYearSession)
  .filter(isAllowedPipelineState);

const sessionsToInspect = filteredSessions.slice(0, maxSessionsDetails);

const detailedSessions = [];
const failedSessions = [];

for (const lightSession of sessionsToInspect) {
  try {
    const detailedSession = await fetchTrainingSessionDetails(lightSession.id);

    if (detailedSession && isTargetYearSession(detailedSession) && isAllowedPipelineState(detailedSession)) {
      detailedSessions.push(detailedSession);
    }
  } catch (error) {
    failedSessions.push({
      id: lightSession.id,
      name: lightSession.name,
      error: error.message
    });
  }
}

const planningResults = buildPlanningResults(detailedSessions);
const reminders = buildSignatureReminders(detailedSessions);

const cachePayload = buildSummary({
  lightSessions,
  filteredSessions,
  detailedSessions,
  failedSessions,
  planningResults,
  reminders
});

const postResult = await postCacheToApp(cachePayload);

return [
  {
    json: {
      success: true,
      message: 'Synchronisation Digiforma terminée',
      postResult,
      summary: {
        generatedAt: cachePayload.generatedAt,
        totalSessionsFetched: cachePayload.planning.totalSessionsFetched,
        totalSessionsAfterFilter: cachePayload.planning.totalSessionsAfterFilter,
        totalSessions: cachePayload.planning.totalSessions,
        totalLearners: cachePayload.planning.totalLearners,
        totalPlanningMissing: cachePayload.planning.totalMissing,
        totalPlanningWarning: cachePayload.planning.totalWarning,
        totalReminders: cachePayload.reminders.totalReminders,
        totalCriticalReminders: cachePayload.reminders.totalCritical,
        totalFailedSessions: cachePayload.planning.totalSessionsFailed
      }
    }
  }
];
